import{_ as e,o as a,c as i,ae as o}from"./chunks/framework.1Lna8NcP.js";const g=JSON.parse('{"title":"Phase 2: Net Worth Dashboard — Design Spec","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-04-12-phase-2-dashboard-design.md","filePath":"superpowers/specs/2026-04-12-phase-2-dashboard-design.md"}'),l={name:"superpowers/specs/2026-04-12-phase-2-dashboard-design.md"};function n(s,t,r,u,c,h){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="phase-2-net-worth-dashboard-—-design-spec" tabindex="-1">Phase 2: Net Worth Dashboard — Design Spec <a class="header-anchor" href="#phase-2-net-worth-dashboard-—-design-spec" aria-label="Permalink to &quot;Phase 2: Net Worth Dashboard — Design Spec&quot;">​</a></h1><p><strong>Date:</strong> 2026-04-12<br><strong>Target users:</strong> 20-40 demographic (wealth builders, debt-conscious, retirement-aware)<br><strong>Vision:</strong> Clarity through simplicity. Open app, immediately know financial situation + what action to take.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Phase 2 transforms Libertas into a complete net worth experience with ruthless focus on what matters. Dashboard prioritizes three things: <strong>see your accounts</strong>, <strong>understand your situation</strong>, <strong>act on what matters most</strong>.</p><p>Core principle: zero cognitive overhead. Account overview + actionable recommendation visible in ❤️ seconds.</p><hr><h2 id="dashboard-layout" tabindex="-1">Dashboard Layout <a class="header-anchor" href="#dashboard-layout" aria-label="Permalink to &quot;Dashboard Layout&quot;">​</a></h2><h3 id="visual-hierarchy-top-to-bottom" tabindex="-1">Visual Hierarchy (top to bottom) <a class="header-anchor" href="#visual-hierarchy-top-to-bottom" aria-label="Permalink to &quot;Visual Hierarchy (top to bottom)&quot;">​</a></h3><p><strong>Hero Section:</strong></p><ul><li>Net worth number (e.g., &quot;$462,761&quot;)</li><li>30-day change (e.g., &quot;+$8,200 | +1.8%&quot;)</li><li>Last updated timestamp</li></ul><p><strong>Recommendation Carousel:</strong></p><ul><li>Single rotating insight from insights engine</li><li>Changes on page refresh</li><li>Pin button to lock current insight</li><li>Example: &quot;Diversify. You&#39;re 45% tech. Add $50k to bonds to hit 40% target.&quot;</li></ul><p><strong>Account Overview:</strong></p><ul><li>Accounts grouped by type: Checking, Savings, Brokerage, Crypto, Real Estate, Debt</li><li>Each account shows: name + balance + status icon (✓ green / ⚠ yellow / 🔴 red)</li><li>Click to navigate to account detail page</li><li>Status based on staleness: green &lt;7d updated, yellow &lt;30d, red &gt;30d</li></ul><p><strong>Secondary Layers (below fold):</strong></p><ul><li>Net worth chart with range selector (1M / 3M / 6M / YTD / 1Y / All)</li><li>Asset allocation donut (includes liabilities)</li><li>All insights carousel (browse full set of 12-15 insight cards)</li></ul><p><strong>Privacy Callout:</strong></p><ul><li>Persistent on dashboard: &quot;Local-first. Your data stays here.&quot;</li></ul><hr><h2 id="recommendation-carousel" tabindex="-1">Recommendation Carousel <a class="header-anchor" href="#recommendation-carousel" aria-label="Permalink to &quot;Recommendation Carousel&quot;">​</a></h2><p><strong>Behavior:</strong></p><ul><li>Displays one insight at a time, rotates to next on page refresh</li><li>User can pin current insight to prevent rotation (pinned insight shows first, others rotate behind it)</li><li>Pin state persisted in browser localStorage</li></ul><p><strong>Content:</strong></p><ul><li>Insight title + context (e.g., &quot;Concentration Risk&quot;)</li><li>Actionable advice in plain English (e.g., &quot;You&#39;re 45% in tech stocks. Consider adding $50k to bonds to hit your 40% target.&quot;)</li><li>Optional metric or benchmark (e.g., &quot;Your ideal range: 30-40%&quot;)</li></ul><p><strong>Visual:</strong></p><ul><li>Prominent card below hero number</li><li>Green border for positive insights, yellow for caution, red for critical</li><li>Pin icon (top right) for locking</li></ul><hr><h2 id="account-overview-cards" tabindex="-1">Account Overview Cards <a class="header-anchor" href="#account-overview-cards" aria-label="Permalink to &quot;Account Overview Cards&quot;">​</a></h2><p><strong>Display (minimal):</strong></p><ul><li>Account type icon + name</li><li>Current balance</li><li>Status indicator (✓/⚠/🔴) based on last_updated timestamp</li></ul><p><strong>Interaction:</strong></p><ul><li>Click card → navigate to account detail page</li><li>Quick-add button (+ icon) → modal for adding transaction / holding / balance update</li></ul><p><strong>Grouping:</strong></p><ul><li>Checking Accounts</li><li>Savings Accounts</li><li>Brokerage / Investment Accounts</li><li>Crypto Accounts</li><li>Real Estate</li><li>Debt (mortgages, loans, credit cards)</li></ul><hr><h2 id="account-detail-page" tabindex="-1">Account Detail Page <a class="header-anchor" href="#account-detail-page" aria-label="Permalink to &quot;Account Detail Page&quot;">​</a></h2><p><strong>Tabs:</strong></p><p><strong>Transactions Tab:</strong></p><ul><li>All transactions for account (searchable, filterable by date / amount / category)</li><li>Sortable by date / amount</li><li>Pagination or infinite scroll</li></ul><p><strong>Holdings Tab</strong> (investment accounts):</p><ul><li>Table: Symbol | Shares | Cost Basis | Current Value | Gain/Loss | % of Portfolio</li><li>Sortable by any column</li></ul><p><strong>Real Estate Tab</strong> (real estate accounts):</p><ul><li>Property details: address, value, mortgage balance, LTV, equity</li><li>Last assessed date</li><li>Mortgage payoff timeline (if applicable)</li></ul><p><strong>Account Header:</strong></p><ul><li>Account name + type</li><li>Current balance (large, prominent)</li><li>Staleness indicator with last-updated timestamp</li><li>Quick-add button</li></ul><hr><h2 id="insights-system" tabindex="-1">Insights System <a class="header-anchor" href="#insights-system" aria-label="Permalink to &quot;Insights System&quot;">​</a></h2><h3 id="insights-engine-12-15-rules-all-rule-based-offline-compatible" tabindex="-1">Insights Engine (12-15 rules, all rule-based, offline-compatible) <a class="header-anchor" href="#insights-engine-12-15-rules-all-rule-based-offline-compatible" aria-label="Permalink to &quot;Insights Engine (12-15 rules, all rule-based, offline-compatible)&quot;">​</a></h3><h4 id="financial-health-5-rules" tabindex="-1">Financial Health (5 rules) <a class="header-anchor" href="#financial-health-5-rules" aria-label="Permalink to &quot;Financial Health (5 rules)&quot;">​</a></h4><ol><li><p><strong>Concentration Risk</strong></p><ul><li>Rule: Flag if any single asset class or sector &gt;40% of portfolio</li><li>Insight: &quot;You&#39;re 45% in tech. Ideal max: 40%. Diversify to reduce volatility.&quot;</li></ul></li><li><p><strong>Liquidity Ratio (Emergency Fund)</strong></p><ul><li>Rule: Compare liquid assets (checking + savings) to monthly expenses</li><li>Insight: &quot;Emergency fund covers 2 months. Ideal: 3-6 months. Build to $X.&quot;</li></ul></li><li><p><strong>Allocation Drift</strong></p><ul><li>Rule: Compare actual asset class allocation to user&#39;s target allocation</li><li>Insight: &quot;Actual: 60% equities, 25% bonds, 15% cash. Target: 50/30/20. Rebalance to align.&quot;</li></ul></li><li><p><strong>Debt-to-Income Ratio</strong></p><ul><li>Rule: (Total debt payments / gross income) × 100</li><li>Insight: &quot;Debt-to-income: 25%. Healthy range: 20-36%. Good position. Consider accelerating payoff.&quot;</li></ul></li><li><p><strong>Asset Class Diversification</strong></p><ul><li>Rule: Count number of asset classes with &gt;0 balance; flag if ❤️</li><li>Insight: &quot;You hold 2 asset classes. Add bonds or real estate for better diversification.&quot;</li></ul></li></ol><h4 id="retirement-long-term-4-rules" tabindex="-1">Retirement &amp; Long-Term (4 rules) <a class="header-anchor" href="#retirement-long-term-4-rules" aria-label="Permalink to &quot;Retirement &amp; Long-Term (4 rules)&quot;">​</a></h4><ol start="6"><li><p><strong>Net Worth Growth Rate</strong></p><ul><li>Rule: Compare 3-month, 6-month, YTD net worth growth</li><li>Insight: &quot;Net worth growing $2,500/mo. At this pace, double your wealth in 14 years.&quot;</li></ul></li><li><p><strong>Retirement Readiness / FIRE Timeline</strong></p><ul><li>Rule: Project net worth growth to user&#39;s FIRE target (from Phase 3)</li><li>Insight: &quot;At $2,500/mo savings, reach FIRE by age 38. On track.&quot;</li></ul></li><li><p><strong>401k / IRA Contribution Rate</strong></p><ul><li>Rule: Compare current year contributions to annual limit ($23,500 401k / $7,000 IRA)</li><li>Insight: &quot;You&#39;ve contributed $5,800 to 401k (25% of limit). Increase by $200/mo to max out.&quot;</li></ul></li><li><p><strong>Compound Growth Projection</strong></p><ul><li>Rule: Project portfolio value 10y forward at 6% annual return</li><li>Insight: &quot;Projected net worth in 10 years: $850k (assuming 6% return, current contributions).&quot;</li></ul></li></ol><h4 id="debt-management-3-rules" tabindex="-1">Debt Management (3 rules) <a class="header-anchor" href="#debt-management-3-rules" aria-label="Permalink to &quot;Debt Management (3 rules)&quot;">​</a></h4><ol start="10"><li><p><strong>Debt Payoff Trajectory</strong></p><ul><li>Rule: Compare current debt balance to 6-month / 1-year ago; extrapolate payoff date</li><li>Insight: &quot;Student loans down 8% YoY. At current pace, paid off by age 32.&quot;</li></ul></li><li><p><strong>Total Interest Burden</strong></p><ul><li>Rule: Sum annual interest across all debt (mortgages, loans, CCs)</li><li>Insight: &quot;You&#39;re paying $1,200/year in interest. Paying extra $100/mo would save $4,800 over 5 years.&quot;</li></ul></li><li><p><strong>Mortgage Affordability</strong> (if applicable)</p><ul><li>Rule: Mortgage balance / home value (LTV); compare to standard benchmarks</li><li>Insight: &quot;LTV: 65%. Conservative. Can afford to take on more debt if needed.&quot;</li></ul></li></ol><h4 id="cash-flow-3-rules" tabindex="-1">Cash Flow (3 rules) <a class="header-anchor" href="#cash-flow-3-rules" aria-label="Permalink to &quot;Cash Flow (3 rules)&quot;">​</a></h4><ol start="13"><li><p><strong>Savings Rate Trend</strong></p><ul><li>Rule: (Income - expenses) / income × 100, tracked monthly</li><li>Insight: &quot;Savings rate: 22% last month, 18% avg. Keep up the savings discipline.&quot;</li></ul></li><li><p><strong>Income Stability / Volatility</strong></p><ul><li>Rule: Coefficient of variation of last 6 months income</li><li>Insight: &quot;Income stable ($5,000±2% monthly). Low volatility—reliable for planning.&quot;</li></ul></li><li><p><strong>Passive vs. Earned Income Breakdown</strong></p><ul><li>Rule: Sum investment returns + other passive income vs. salary</li><li>Insight: &quot;Passive income: $200/mo (2% of total). Focus: increase passive streams for flexibility.&quot;</li></ul></li></ol><h3 id="insights-display" tabindex="-1">Insights Display <a class="header-anchor" href="#insights-display" aria-label="Permalink to &quot;Insights Display&quot;">​</a></h3><ul><li><strong>All Insights Carousel:</strong> Browse all 12-15 insights below fold</li><li><strong>Insight Cards:</strong> Each shows rule name, current status, actionable advice</li><li><strong>Color coding:</strong> Green (healthy), yellow (caution), red (critical)</li><li><strong>Offline guarantee:</strong> All rules compute from local SQLite, no external API calls</li></ul><hr><h2 id="data-computation" tabindex="-1">Data &amp; Computation <a class="header-anchor" href="#data-computation" aria-label="Permalink to &quot;Data &amp; Computation&quot;">​</a></h2><h3 id="monthly-snapshots" tabindex="-1">Monthly Snapshots <a class="header-anchor" href="#monthly-snapshots" aria-label="Permalink to &quot;Monthly Snapshots&quot;">​</a></h3><ul><li>Auto-captured at end of each calendar month</li><li>Fields: date, net_worth, allocation (asset class breakdown), snapshot_source</li><li>Used for historical net worth chart</li></ul><h3 id="staleness-tracking" tabindex="-1">Staleness Tracking <a class="header-anchor" href="#staleness-tracking" aria-label="Permalink to &quot;Staleness Tracking&quot;">​</a></h3><ul><li>Account.last_updated timestamp maintained</li><li>Status: green (&lt;7d), yellow (&lt;30d), red (&gt;30d)</li><li>Visual indicator on account card + account detail</li></ul><h3 id="insights-computation" tabindex="-1">Insights Computation <a class="header-anchor" href="#insights-computation" aria-label="Permalink to &quot;Insights Computation&quot;">​</a></h3><ul><li>Computed on-demand when dashboard loads (cache results for 1 hour or on manual refresh)</li><li>Deterministic, rule-based (no ML)</li><li>Store rule outputs (score, status, explanation) in insights cache table</li></ul><hr><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ol><li>Dashboard &lt;500ms render on local SQLite (hero + accounts + top recommendation)</li><li>All Tier 1 features complete (hero, allocation, chart, accounts, monthly snapshots)</li><li>Recommendation carousel works (rotates on refresh, pin persists)</li><li>12-15 insights rules all implemented, tested, offline-compatible</li><li>Allocation donut includes liabilities</li><li>Account overview scannable in ❤️ seconds</li><li>Per-account detail views (transactions, holdings, real estate) fully functional</li><li>All insights compute offline, deterministic results</li></ol><hr><h2 id="execution-plan" tabindex="-1">Execution Plan <a class="header-anchor" href="#execution-plan" aria-label="Permalink to &quot;Execution Plan&quot;">​</a></h2><p>Five sub-phases (mapped to .planning/phases/02-net-worth-dashboard/):</p><ol><li><strong>02-01:</strong> Backend history + snapshot cadence APIs</li><li><strong>02-02:</strong> Dashboard hero + allocation + recommendation carousel + account overview UI</li><li><strong>02-03:</strong> Account detail pages (transactions, holdings, real estate)</li><li><strong>02-04:</strong> Insights engine (12-15 rules) + insight cards UI</li><li><strong>02-05:</strong> Final polish + performance profiling + ADR</li></ol><hr><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>FIRE goal visualization (Phase 3: Onboarding &amp; FIRE)</li><li>Comparison features vs. benchmarks (handled via insights)</li><li>Rebalance / move money actions (Phase 3+)</li><li>Alerts (future phase)</li></ul>',77)])])}const p=e(l,[["render",n]]);export{g as __pageData,p as default};
